export class LegacyReaderLists{
 constructor(panel){this.panel=panel}
 renderToc(items,jump){const list=this.panel.querySelector('[data-toc]');list.replaceChildren();const add=(items,depth=0)=>{for(const item of items||[]){if(item.href!=null){const b=document.createElement('button');b.type='button';b.textContent=item.label||'Capítulo';b.style.paddingInlineStart=(12+Math.min(4,depth)*12)+'px';b.onclick=()=>jump(item.href);list.append(b)}if(depth<8)add(item.subitems,depth+1)}};add(items);this.panel.querySelector('[data-place-tab=toc]').hidden=!list.childElementCount;return !!list.childElementCount}
 renderPlaces(name,places,labels,select,remove,icon){const list=this.panel.querySelector('[data-'+name+']');list.replaceChildren();if(!places.length){const empty=document.createElement('p');empty.className='reading-hint';empty.textContent=name==='history'?'Sin recientes':name==='quotes'?'Sin citas':'Sin marcadores';list.append(empty)}places.forEach((place,index)=>{const row=document.createElement('div');row.className='reading-place';const button=document.createElement('button');button.type='button';button.textContent=name==='quotes'?'“'+place.text+'” · '+labels[index]:labels[index];button.onclick=()=>select(index,place);const del=document.createElement('button');del.type='button';del.innerHTML=icon;del.setAttribute('aria-label','Eliminar '+labels[index]);del.onclick=()=>remove(index,place);row.append(button,del);list.append(row)})}
 clearSearch(message){this.panel.querySelector('[data-search-results]').replaceChildren();this.panel.querySelector('[data-search-status]').textContent=message}
 renderSearch(results,select){this.clearSearch('');const status=this.panel.querySelector('[data-search-status]'),list=this.panel.querySelector('[data-search-results]');status.textContent=results.length?results.length+' '+(results.length===1?'resultado':'resultados'):'Sin resultados';for(const result of results){const b=document.createElement('button');b.type='button';b.className='reading-search-hit';if(result.label){const where=document.createElement('small');where.textContent=result.label;b.append(where)}const line=document.createElement('span'),{pre=result.excerpt||'',match='',post=''}=result.parts||{};if(match){const mark=document.createElement('mark');mark.textContent=match;line.append(pre,mark,post)}else line.textContent=pre;b.append(line);b.onclick=()=>select(result);list.append(b)}}
}
